  switch (variable) {
  case NPNVjavascriptEnabledBool:
  case NPNVasdEnabledBool:
   case NPNVisOfflineBool:
   case NPNVSupportsXEmbedBool:
   case NPNVSupportsWindowless:
 	type = RPC_TYPE_BOOLEAN;
 	break;
   case NPNVToolkit:
